@font-face{font-family:Inter;src:url('dependencies/Inter-Variable.ttf') format('truetype');font-weight:100 900;font-style:normal;font-display:block}
*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;color:#334155;background:#fff;font:17px/1.65 Inter,Arial,sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer}a{color:#008078}a:visited{color:#062b5b}a:focus-visible,button:focus-visible{outline:3px solid #008078;outline-offset:3px}a:hover{text-decoration:underline;text-underline-offset:5px}h1,h2,h3,p{margin:0}h1,h2,h3{color:#062b5b;line-height:1.18}h1{font-size:54px;letter-spacing:-.025em;max-width:930px;font-weight:700}h2{font-size:34px;font-weight:700}h3{font-size:24px;font-weight:600}p{margin-bottom:20px}p:last-child{margin-bottom:0}.page-width{width:min(1200px,calc(100% - 64px));margin:auto}.hero{padding:0 0 52px;background:#f5f8fb}.breadcrumb{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;padding:22px 0 30px;font-size:14px}.breadcrumb a{min-width:44px;min-height:44px;display:inline-flex;align-items:center;color:#334155;padding:0 4px}.hero-copy{max-width:900px;margin-top:24px}.hero-copy p{font-size:20px;line-height:1.65}.body-action{display:inline-flex;margin-top:8px;margin-right:16px;max-width:100%}.body-action a{display:inline-flex;align-items:center;justify-content:center;min-width:44px;min-height:48px;padding:11px 18px;max-width:100%;text-align:center;border:1px solid #062b5b;border-radius:6px;color:#062b5b;font-size:16px;font-weight:600;text-decoration:none;line-height:1.45}.body-action a:hover{background:#e8eef3}.body-action+.body-action a{border-color:transparent;text-decoration:underline;text-underline-offset:5px;padding-left:0;padding-right:0}.section-grid{display:grid;grid-template-columns:340px minmax(0,1fr);gap:72px}.section-copy{max-width:790px}.application-paths{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin:30px 0 20px}.application-path{border-top:1px solid #a4b4c4;padding:22px 0 0}.application-path h3{margin-bottom:16px}main a:focus-visible{outline:3px solid #008078;outline-offset:4px}
/* Read-only shared CSS is consumed above. These planning adapters reconcile its
   old values with current approved Chrome/Logo/CTA/legal contracts, not a new owner version. */
.header,.footer{font-family:Inter,Arial,sans-serif}.header{height:84px;border-color:#d9e2ec;color:#062b5b}.headerInner{width:min(1200px,calc(100% - 64px));height:83px;min-height:0;gap:24px}.logoLink{min-width:180px;min-height:60px}.desktopNav{gap:16px}.desktopNav a{font-size:14px;color:#062b5b;font-weight:500}.desktopNav a[aria-current='page']{font-weight:700}.desktopNav a[aria-current='page']::after{background:#008078}.header .headerRfq,.footer .footerRfq{font-size:14px;min-width:44px;min-height:48px;border-radius:6px;background:#008078;border-color:#008078;color:white;padding:0 18px}.header :is(a,button):focus-visible{outline:3px solid #008078}.footer{padding:52px max(32px,calc((100% - 1200px)/2)) 28px}.footerGrid{gap:48px}.footer .brandColumn p,.footer .copyright{font-size:14px;max-width:295px}.footer h2{font-size:14px;line-height:1.4}.footer .footerGrid a{font-size:14px;font-weight:500;min-width:44px}.footer .footerRfq{font-weight:600}.footer .legalUtilities :is(a,button){font:500 14px/1.5 Inter,Arial,sans-serif;min-width:44px;min-height:44px;display:inline-flex;align-items:center}.footer .copyright{font-size:14px!important}.footer :is(a,button):focus-visible{outline:3px solid white}.footerLogo{width:180px;height:60px}.menuButton{font:600 14px Inter,Arial,sans-serif;border-radius:6px}.header nav.mobileNav>a{font-size:16px}.mobileNav a:last-child{background:#008078}.mobileNav a[aria-current='page']::before{background:#00a99d}.mobileNav a:focus-visible{outline:3px solid white;outline-offset:-4px}.cookie-layer{width:min(560px,calc(100% - 32px));max-height:calc(100% - 32px);padding:32px;border:1px solid #d9e2ec;border-radius:8px;background:white;color:#334155;overflow:auto}.cookie-layer::backdrop{background:rgb(3 27 58 / 72%)}.cookie-layer h2{font-size:30px;margin-bottom:18px}.cookie-layer p{font-size:16px;line-height:1.65}.cookie-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.cookie-actions>*{font:600 14px/1.4 Inter,Arial,sans-serif;min-height:48px;min-width:44px;padding:12px 18px;border:1px solid #062b5b;border-radius:6px;background:white;color:#062b5b;display:inline-flex;align-items:center;justify-content:center;text-decoration:none}
@media(max-width:1100px){.header{height:64px}.headerInner{height:63px;gap:8px;width:calc(100% - 32px)}.logoLink{min-width:120px;min-height:44px}.logo{width:120px;height:40px}.desktopNav,.rfqFull{display:none}.rfqCompact,.menuButton{display:inline}.header .headerRfq{min-height:44px;padding:0 14px}.menuButton{min-height:44px;min-width:64px;padding:0 12px;border:1px solid #062b5b;background:white;color:#062b5b}.mobileNav{position:absolute;top:63px;left:0;right:0;display:grid;grid-template-columns:1fr;color:white;background:#031b3a;max-height:calc(100vh - 64px);overflow:auto}.mobileNav[hidden]{display:none}.header nav.mobileNav>a{position:relative;min-height:52px;padding:10px 24px;display:flex;align-items:center;justify-content:flex-start;flex-direction:row;border-bottom:1px solid #234665;color:#fff;font-weight:500}.header nav.mobileNav>a[aria-current='page']{font-weight:700;padding-left:32px}.mobileNav a[aria-current='page']::before{content:'';position:absolute;top:8px;bottom:8px;left:16px;width:4px}.mobileNav a:last-child{background:#008078;font-weight:600}.page-width{width:calc(100% - 64px)}h1{font-size:44px}h2{font-size:31px}.section-grid{grid-template-columns:1fr;gap:22px}.hero{padding-top:0}.application-paths{gap:32px}.footerGrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:36px 32px}.brandColumn,.conversionColumn{grid-column:1/-1}.footer .brandColumn p{max-width:420px}}
@media(max-width:560px){body{font-size:17px}.page-width{width:calc(100% - 40px)}h1{font-size:36px;line-height:1.16}h2{font-size:29px;line-height:1.22}h3{font-size:23px}.breadcrumb{padding:16px 0 22px;gap:2px 6px}.hero-copy{margin-top:22px}.hero-copy p{font-size:18px}.hero{padding-top:0}.section-grid{gap:20px}.application-paths{grid-template-columns:1fr;gap:28px;margin:26px 0 18px}.application-path{padding-top:20px}.body-action{display:flex;margin-right:0;margin-top:12px}.body-action a{width:100%;font-size:16px}.body-action+.body-action a{justify-content:flex-start;text-align:left}.footer{padding:36px 20px 24px}.footerGrid{gap:32px 20px}.footerLogo{width:180px;height:60px}.footer .copyright{margin-top:16px!important}.cookie-layer{padding:26px 20px}.cookie-layer h2{font-size:26px}.cookie-actions>*{width:100%}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
